import { AppShell } from '@/components/AppShell';
import { Main } from '@/components/Main';

const page = <Main.Content><p>Select a finding to review its details.</p></Main.Content>;
const details = <Main.Content><p>The selected finding is ready for review.</p></Main.Content>;

<AppShell>
  <AppShell.Main>
    <Main>{page}</Main>
  </AppShell.Main>
  <AppShell.Aside aria-label="Details">
    <Main as="div">{details}</Main>
  </AppShell.Aside>
</AppShell>

import { AppShell } from '@/components/AppShell';
import { Header } from '@/components/Header';
import { Sidebar } from '@/components/Sidebar';

const nav = (
  <Sidebar.Nav>
    <Sidebar.Section label="Workspace">
      <Sidebar.Item href="/overview" active>Overview</Sidebar.Item>
      <Sidebar.Item href="/findings">Findings</Sidebar.Item>
    </Sidebar.Section>
  </Sidebar.Nav>
);
const page = <p>Workspace overview</p>;

<AppShell collapsible="offcanvas" defaultCollapsed>
  <AppShell.Header>
    <Header>
      <Header.Trigger />
      <Header.Brand href="/">Fragments</Header.Brand>
    </Header>
  </AppShell.Header>
  <AppShell.Sidebar>{nav}</AppShell.Sidebar>
  <AppShell.Main>{page}</AppShell.Main>
</AppShell>
